<!-- wp:wdl/lw-qa-1 {"blockId":"lw-qa-1-esthe2-bridal","mainColor":"#2f3437"} -->
<div class="wp-block-wdl-lw-qa-1 lw-qa-1" id="lw-qa-1-esthe2-bridal"><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto" style="font-weight:">Q<div style="background:#2f3437"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="" style="font-weight:">いつから始めればいいですか。</p></div><div class="open_icon" style="background:#2f3437"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="font-weight:;color:#2f3437">A<div style="background:#2f3437"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="" style="font-weight:">3か月前がいちばん多いです。背中のざらつきなど時間のかかるものに手を入れたい場合は6か月前、むくみと肌のトーンだけなら1か月前からでも間に合います。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto" style="font-weight:">Q<div style="background:#2f3437"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="" style="font-weight:">式の直前に肌が荒れないか心配です。</p></div><div class="open_icon" style="background:#2f3437"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="font-weight:;color:#2f3437">A<div style="background:#2f3437"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="" style="font-weight:">直前3日間は施術を行いません。またコースの後半は新しいことを足さず、保湿とトーンアップだけに絞ります。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto" style="font-weight:">Q<div style="background:#2f3437"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="" style="font-weight:">日程がずれても大丈夫ですか。</p></div><div class="open_icon" style="background:#2f3437"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="font-weight:;color:#2f3437">A<div style="background:#2f3437"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="" style="font-weight:">振り替えは何度でも承ります。準備でご予定が動くのは当たり前ですので、キャンセル料はいただきません（前日までにご連絡ください）。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto" style="font-weight:">Q<div style="background:#2f3437"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="" style="font-weight:">背中だけお願いできますか。</p></div><div class="open_icon" style="background:#2f3437"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="font-weight:;color:#2f3437">A<div style="background:#2f3437"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="" style="font-weight:">できます。ドレスが決まってから背中だけを追加される方が多いです。1回11,000円で承ります。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto" style="font-weight:">Q<div style="background:#2f3437"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="" style="font-weight:">妊娠中でも受けられますか。</p></div><div class="open_icon" style="background:#2f3437"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="font-weight:;color:#2f3437">A<div style="background:#2f3437"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="" style="font-weight:">安定期に入っていればお受けいただけます。うつぶせにならない姿勢で行いますので、ご予約のときにお知らせください。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto" style="font-weight:">Q<div style="background:#2f3437"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="" style="font-weight:">新郎も一緒に受けられますか。</p></div><div class="open_icon" style="background:#2f3437"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="font-weight:;color:#2f3437">A<div style="background:#2f3437"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="" style="font-weight:">フェイシャルのみ承ります。当サロンは女性専用のため、おふたりでの同伴予約に限らせていただいています。</p></div></dd></dl><script>
(function(){
	const scriptEl  = document.currentScript;
	if ( !scriptEl ) return;
	const container = scriptEl.parentNode;           // <script> の親 = lw-qa-1 本体
	if ( !container || !container.classList.contains('lw-qa-1') ) return;

	/* クリックイベントをバインド ---------------------- */
	function bind () {
		container.querySelectorAll(".lw-qa-1__dl").forEach( function( dl ){
			if ( dl.dataset.lwQaBound ) return;      // 二重バインド防止
			dl.dataset.lwQaBound = "1";
			dl.addEventListener("click", function(){ dl.classList.toggle("active"); } );
		} );
	}

	bind(); // まず 1 回

	/* MutationObserver – QA が動的に増減しても OK */
	const mo = new MutationObserver(bind);
	mo.observe(container,{ childList:true, subtree:true });
})();
		</script></div>
<!-- /wp:wdl/lw-qa-1 -->

