<!-- wp:wdl/lw-voice-1 {"h2FontSet":"Shippori Mincho","h2FontWeight":"500","h2TextColor":"#2f3437","nameBackgroundColor":"#2f3437","nameFontSet":"","h3TextColor":"#2f3437","h3FontSet":"Shippori Mincho","pTextColor":"#3a3733","pFontSet":"","backgroundColor":"#f4f1ec"} -->
<div class="wp-block-wdl-lw-voice-1 lw-voice-1" style="background-color:#f4f1ec"><h2 class="lw-voice-1__title" style="font-weight:500;color:#2f3437" data-lw_font_set="Shippori Mincho">お客様の声</h2><ul class="lw-voice-1__ul"><li class="lw-voice-1__li"><div class="lw-voice-1__name" style="background-color:#2f3437;color:#ffffff;font-weight:500" data-lw_font_set="">鎌倉市 30代 A様</div><div class="lw-voice-1__text"><h3 style="color:#2f3437;font-weight:500" data-lw_font_set="Shippori Mincho">3か月前からで間に合うと言ってもらえて、安心しました。</h3><p style="color:#3a3733;font-weight:500" data-lw_font_set="">ドレスを決めてから背中が大きく開くと気づいて、慌てて探しました。当日、母に「背中がきれい」と言われたのがいちばんうれしかったです。</p></div></li><li class="lw-voice-1__li"><div class="lw-voice-1__name" style="background-color:#2f3437;color:#ffffff;font-weight:500" data-lw_font_set="">横浜市 30代 R様</div><div class="lw-voice-1__text"><h3 style="color:#2f3437;font-weight:500" data-lw_font_set="Shippori Mincho">施術の日が、何も考えずに眠れる時間になりました。</h3><p style="color:#3a3733;font-weight:500" data-lw_font_set="">直前は打ち合わせで疲れていましたが、ここに来る日だけは頭を空にできました。振り替えを何度も聞いていただけたのも助かりました。</p></div></li><li class="lw-voice-1__li"><div class="lw-voice-1__name" style="background-color:#2f3437;color:#ffffff;font-weight:500" data-lw_font_set="">鎌倉市 20代 H様</div><div class="lw-voice-1__text"><h3 style="color:#2f3437;font-weight:500" data-lw_font_set="Shippori Mincho">前撮りの写真が、自分でも見返せるものになりました。</h3><p style="color:#3a3733;font-weight:500" data-lw_font_set="">1か月前からの直前コースでした。できることは絞られると最初に言われたぶん、期待どおりでした。二の腕のむくみが取れたのが大きかったです。</p></div></li></ul></div>
<!-- /wp:wdl/lw-voice-1 -->

